fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Precondition (can be omitted if you trust the caller):
    debug_assert!(!list.is_empty(), "list must be non-empty");
    debug_assert!(n > 0 && n < list.len(), "n must satisfy 0 < n < list.len()");

    let len = list.len();
    // Allocate a new Vec with the exact capacity we need.
    let mut new_list = Vec::with_capacity(len);
    // First append the tail slice from n..len
    new_list.extend_from_slice(&list[n..]);
    // Then append the head slice from 0..n
    new_list.extend_from_slice(&list[..n]);

    new_list
}

